using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notepad = new Notepad();

var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information (make 2-3 searches with different queries).
        2. Save key findings as notes using the note-taking tool.
        3. After gathering enough information, produce a concise summary of your findings.
        Always cite the sources you found. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools:
    [
        AIFunctionFactory.Create(WebSearchTool.SearchAsync),
        AIFunctionFactory.Create(notepad.SaveNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]);

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input)
{
    input = input.Trim();
    if (string.Equals(input, "quit", StringComparison.OrdinalIgnoreCase) || input.Length == 0)
    {
        break;
    }

    Console.WriteLine($"\nResearching: {input}\n");

    try
    {
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic and provide a summary: {input}",
            session: null,
            options: null))
        {
            Console.Write(update.Text);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError: {ex.Message}");
    }

    notepad.Clear();
    Console.WriteLine("\n\nEnter another topic (or 'quit' to exit):");
    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Simulated web search tool that returns plausible results for demonstration purposes.
/// Replace with a real search API (e.g., Bing Search) for production use.
/// </summary>
static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static Task<string> SearchAsync(
        [Description("The search query to look up on the web.")] string query)
    {
        // Simulated search results for demonstration.
        // In production, call a real search API such as Bing Web Search.
        var results = $"""
            Search results for: "{query}"

            1. Wikipedia - {query}
               URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
               Snippet: {query} is a well-documented subject with extensive research and
               community interest. Multiple studies and articles cover various aspects of this topic.

            2. Research Paper - Recent Advances in {query}
               URL: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}
               Snippet: This paper surveys the latest developments and key findings related to
               {query}, highlighting emerging trends and future directions.

            3. News - Latest on {query}
               URL: https://news.example.com/{Uri.EscapeDataString(query)}
               Snippet: Recent reports indicate growing interest in {query}, with new developments
               being announced by leading organizations and research institutions.
            """;

        return Task.FromResult(results);
    }
}

/// <summary>
/// Note-taking tool that allows the agent to save and retrieve research notes.
/// </summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note for later reference in the summary.")]
    public string SaveNote(
        [Description("The note content to save, including source attribution.")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
        }

        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

